import {
  CheckCircle,
  Eye,
  FileSlidersIcon,
  FileText,
  Layers,
  List,
  XCircle
} from 'lucide-react';

import FormSaveForm from '@/Components/Forms/Backend/Form/FormSaveForm';
import { Button } from '@/Components/UI/Button';
import { useTranslations } from '@/Hooks/useTranslations';
import type { CrudConfig, CrudPageProps } from '@/Types/crud';
import { router } from '@inertiajs/react';
import React from 'react';
import z from 'zod';

export function useFormConfig(props: CrudPageProps): CrudConfig {

  const { t } = useTranslations();

  const modelProperty = props?.modelProperty;
  const advanceFilterOptions = props?.advanceFilterOptions || [];
  const routePrefix = modelProperty?.routePrefix;

  const baseBreadcrumbs = [
    { label: t('Dashboard'), href: route('backend.dashboard') },
    { label: t('Forms'), href: route(`${routePrefix}.index`) },
  ];

  return {

    formComponent: FormSaveForm,
    fetchToggle: true,
    form: {
      title: {
        create: t('Create Form'),
        edit: t('Edit Form'),
      },
      description: {
        create: t('Add a new form to the system'),
        edit: t('Update form information'),
      },
      submitButtonText: {
        create: t('Create Form'),
        edit: t('Update Form'),
      },

      fields: [
        {
          name: 'name',
          label: t('Name'),
          type: 'text',
          placeholder: t('Enter form name'),
          required: true,
          gridColumn: 'span 3',
          validation: z.string().min(1, 'Name is required').max(191)
        },
        {
          name: 'description',
          label: t('Description'),
          type: 'textarea',
          placeholder: t('Enter form description'),
          required: false,
          gridColumn: 'span 3',
          validation: z.string().max(500).optional()
        },

      ],
    },

    formValidationRules: {
      name: z.string().min(1, 'Name is required').max(191),
      description: z.string().max(500).optional()
    },

    resource: 'form',
    resourcePlural: 'forms',
    title: t('Form'),
    description: t('Manage system forms'),

    routes: {
      index: `${routePrefix}.index`,
      update: `${routePrefix}.update`,

    },

    formDisplayMode: 'modal',
    viewDisplayMode: 'modal',
    statusType: 'binary',

    breadcrumbs: {
      index: [
        { label: t('Dashboard'), href: route('backend.dashboard') },
        { label: t('Forms'), href: null, active: true },
      ],
      create: [
        ...baseBreadcrumbs,
        { label: t('Create'), href: null, active: true },
      ],
      update: [
        ...baseBreadcrumbs,
        { label: t('Update'), href: null, active: true },
      ],
    },

    table: {
      selectable: false,
      searchable: true,
      serializable: true,
      searchPlaceholder: t('Search forms by name'),
      sortable: true,
      defaultSort: 'created_at',
      defaultSortDirection: 'desc',
      emptyMessage: t('No forms available. Create your first form to get started.'),
      emptyMessageIcon: FileText,


      columns: [

        {
          key: 'name',
          label: t('Name'),
          sortable: false,
          filterable: true,
          priority: 0,
          defaultIcon: FileText,
        },
        {
          key: 'fields',
          label: t('Fields'),
          sortable: false,
          filterable: false,
          priority: 1,
          render: (row: any) => {
            const fieldsCount = row?.fields_count || 0;

            return (

              !row?.deleted_at ?
                <Button
                  onClick={() => {
                    router.visit(route(`${routePrefix}.fields.index`, { form: row.uuid }));
                  }}
                  className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${'bg-blue-50 text-blue-700 hover:bg-blue-100 border border-blue-200 dark:bg-blue-900/20 dark:text-blue-300 dark:border-blue-800 dark:hover:bg-blue-900/30'
                    }`}
                >
                  <Eye className="w-3.5 h-3.5" />
                  {t('View All')} ({fieldsCount})
                </Button>
                : "-"
            );
          },
        },

        {
          key: 'creator',
          label: t('Audit Info'),
          sortable: false,
          filterable: true,
          priority: 1,
          render: (row: any) => (
            <div className="flex flex-col space-y-1.5">
              {/* Created By */}
              <div className="flex items-center gap-1.5 text-sm font-medium text-gray-900 dark:text-gray-100">
                <span className="text-gray-500 dark:text-gray-400">{t('Created By')}:</span>
                <span>{row?.createdBy?.name ?? 'N/A'}</span>
              </div>

              {/* Updated By */}
              <div className="flex items-center gap-1.5 text-xs text-gray-600 dark:text-gray-400">
                <span className="text-gray-500 dark:text-gray-400">{t('Updated By')}:</span>
                <span>{row?.updatedBy?.name ?? 'N/A'}</span>
              </div>
            </div>
          ),
        },

        {
          key: 'created_at',
          label: t('Created At'),
          sortable: false,
          priority: 4,
          renderType: 'date',
        }

      ],

      customActionSubmenus: [
        {
          key: 'form_actions',
          title: t('Form Actions'),
          icon: FileSlidersIcon,
          type: 'route',
          permission: 'form-field.view',
          actions: [
            {
              key: 'fields',
              label: t('Fields'),
              icon: List,
              iconColor: 'text-blue-600',
              permission: 'form-field.view',
              route: `${routePrefix}.fields.index`,
              routeParams: (item: any) => ({ id: item.uuid }),
              target: '_self',
            },

          ],
        },
      ],
    },

    stats: [
      {
        key: 'total',
        title: 'Total Forms',
        icon: Layers,
        iconColor: 'text-blue-600',
        iconBgColor: 'bg-blue-100 dark:bg-blue-900',
        description: 'All form entries'
      },
      {
        key: 'active',
        title: 'Active',
        icon: CheckCircle,
        iconColor: 'text-green-600',
        iconBgColor: 'bg-green-100 dark:bg-green-900',
        description: 'Active forms'
      },
      {
        key: 'inactive',
        title: 'Inactive',
        icon: XCircle,
        iconColor: 'text-red-600',
        iconBgColor: 'bg-red-100 dark:bg-red-900',
        description: 'Inactive forms'
      },

    ],

    filters: {
      searchFields: ['name'],
      filterFields: advanceFilterOptions,
    },

    permissions: {
      actions: {
        edit: 'form.edit',
        view: 'form.view',

      },
    },

    actionConstraints: {
      delete: [],
      bulkDelete: [],
    },

    destroyDialogConfig: {
      title: t('Delete Form'),
      description: t('Are you sure you want to delete this form? This action cannot be undone.'),
      itemName: {
        label: t('Form Name'),
        key: 'name',
        render: (name: string) => name
      },

      itemType: 'Form',
      warningMessage: t('Deleting this form will remove it from the system.'),
      showWarningAlert: true,
      showItemDetails: true,
      itemDisplayFields: [
        {
          label: t('Form Name'),
          key: 'name',
          className: 'font-semibold text-gray-900 dark:text-gray-100'
        },

        {
          label: t('Created By'),
          key: 'createdBy',
          render: (createdBy: any) => React.createElement(
            'span',
            { className: 'text-sm text-gray-700 dark:text-gray-300' },
            createdBy?.name || 'Unknown'
          )
        },
        {
          label: t('Status'),
          key: 'status',
          render: (status: string) => React.createElement(
            'span',
            {
              className: `inline-flex items-center px-2 py-1 rounded-full text-xs font-medium capitalize ${status === 'active'
                ? 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200'
                : 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-200'
                }`
            },
            status
          )
        }
      ]
    },

    labels: {
      singular: 'Form',
      plural: 'Forms',
    },

    saveAlertInfo: {
      title: t('Form Configuration'),
      description: t('Fill in the details below to save the form. All fields marked as required must be completed.'),
    }
  }
};